text:
.scope {
  --tpl-card: var(--card);
  --tpl-line: color-mix(
    in srgb,
    var(--accent) 14%,
    var(--color-templates-tpl-line-1)
  );
  --tpl-line-hover: var(--border-hover);
  --tpl-muted: var(--body);
  --tpl-inset: color-mix(in srgb, var(--accent) 6%, transparent);
  --tpl-token: var(--link);
  --tpl-gradient: var(--button-gradient);
  --tpl-button-text: var(--button-foreground);
  --tpl-upgrade-line: color-mix(in srgb, var(--accent) 30%, var(--card));
  --tpl-upgrade-shadow: 0 8px 28px var(--color-templates-tpl-upgrade-shadow-2);
  --tpl-focus: var(--accent);
  --batch-shadow-scale: 0.55;
}
:global([data-theme="dark"]) .scope {
  --tpl-card: var(--color-templates-tpl-card-3);
  --tpl-line: var(--color-templates-tpl-line-4);
  --tpl-line-hover: var(--color-templates-tpl-line-hover-5);
  --tpl-muted: var(--color-templates-tpl-muted-6);
  --tpl-inset: var(--color-templates-tpl-inset-7);
  --tpl-token: var(--color-templates-tpl-token-8);
  --tpl-gradient: linear-gradient(
    135deg,
    var(--color-templates-tpl-gradient-9),
    var(--color-templates-tpl-token-8)
  );
  --tpl-button-text: var(--color-templates-tpl-button-text-10);
  --tpl-upgrade-line: transparent;
  --tpl-upgrade-shadow: 0 0 44px var(--color-templates-tpl-upgrade-shadow-11);
  --tpl-focus: var(--color-templates-tpl-token-8);
  --batch-shadow-scale: 1;
  color: var(--color-templates-color-12);
}
.scope :is(a, button, input, summary, [tabindex]):focus-visible {
  outline: 2px solid var(--tpl-focus);
  outline-offset: 2px;
}
.chevron svg {
  transition: transform 0.2s;
}
.rotated {
  transform: rotate(90deg);
}
.meter::-webkit-meter-bar {
  background: var(--tpl-line);
  border: 0;
  height: 6px;
}
.meter::-webkit-meter-optimum-value {
  background: var(--tpl-gradient);
}
.meter::-moz-meter-bar {
  background: var(--tpl-gradient);
}
@media (prefers-reduced-motion: reduce) {
  .scope *,
  .scope *::before,
  .scope *::after {
    transition: none !important;
    animation: none !important;
  }
}
.pagination a {
  border-color: var(--tpl-line);
  border-radius: 999px;
}

:global(html[data-workspace][data-appearance="vercel"]) .scope {
  --tpl-card: var(--card);
  --tpl-line: var(--border);
  --tpl-line-hover: var(--border-hover);
  --tpl-muted: var(--body);
  --tpl-inset: var(--surface);
  --tpl-token: var(--highlight-foreground);
  --tpl-gradient: linear-gradient(var(--foreground), var(--foreground));
  --tpl-button-text: var(--background);
  --tpl-upgrade-line: var(--border);
  --tpl-upgrade-shadow: none;
  --tpl-focus: var(--ring);
  color: var(--foreground);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.card, .planPanel, .upgradePanel, .creation, .preview, .search) {
  border-radius: var(--appearance-radius);
}
:global(html[data-workspace][data-appearance="vercel"]) .primary {
  border-radius: var(--appearance-control-radius);
  box-shadow: none;
}
:global(html[data-workspace][data-appearance="vercel"]) .token {
  background: var(--highlight-background);
  color: var(--highlight-foreground);
  border: 1px solid var(--highlight-border);
  border-radius: var(--appearance-badge-radius);
}

:global(html[data-workspace][data-appearance="vercel"])
  .meter::-webkit-meter-optimum-value {
  background: var(--progress-fill);
}
:global(html[data-workspace][data-appearance="vercel"]) .meter::-moz-meter-bar {
  background: var(--progress-fill);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.chevron, .actions > a, .activeActions > a, .pagination a, .search) {
  border-radius: var(--appearance-control-radius);
}
